#!/usr/bin/env bash
# Build the Forge instrumentation bridge.
#
# Three phases, because InstrumentedController.java is generated by reflecting
# over the Forge jar rather than hand-written:
#   1. compile the generator
#   2. run it to emit InstrumentedController.java
#   3. compile everything together
set -euo pipefail

cd "$(dirname "$0")"

FORGE_JAR="${FORGE_JAR:-/usr/share/java/forge-gui-desktop.jar}"
if [[ ! -f "$FORGE_JAR" ]]; then
  echo "error: Forge jar not found at $FORGE_JAR" >&2
  echo "set FORGE_JAR=/path/to/forge-gui-desktop.jar" >&2
  exit 1
fi

mkdir -p build out

echo "[1/3] compiling generator..."
javac -nowarn -cp "$FORGE_JAR" -d build \
  src/magicnet/bridge/ControllerGen.java

echo "[2/3] generating InstrumentedController..."
java -cp "build:$FORGE_JAR" magicnet.bridge.ControllerGen \
  src/magicnet/bridge/GeneratedController.java

echo "[3/3] compiling bridge..."
javac -nowarn -cp "$FORGE_JAR" -d build \
  src/magicnet/bridge/*.java

echo "done. run ./run.sh --decks DIR --games N"
